'use client';

import {useEffect, useId, useRef, useState, type ReactNode} from 'react';
import './integration-settings.css';

export interface IntegrationValues {
  enabled: boolean;
  apiKey: string;
  siteUrl: string;
  timeZone: string;
}

export interface IntegrationReferenceProps {
  /** Explicit opt-in to the original API-key/site/time-zone fidelity fixture. */
  variant: 'reference';
  name: string;
  logo?: ReactNode;
  count?: number;
  meta?: string;
  value: IntegrationValues;
  dirty: boolean;
  onChange: (value: IntegrationValues) => void;
  onSave: (value: IntegrationValues) => void;
  onDiscard: () => void;
  timeZones: readonly string[];
  siteHint?: string;
  validateSite?: (siteUrl: string) => string | undefined;
  /** Caller owns key creation. There is no built-in random key generator. */
  onGenerateKey?: () => void;
  keyPending?: boolean;
  keyIsNew?: boolean;
  onCopyKey?: (key: string) => void | Promise<void>;
  className?: string;
}

export interface IntegrationFormProps {
  variant?: 'integration';
  name: string;
  logo?: ReactNode;
  count?: number;
  meta?: string;
  enabled?: boolean;
  onEnabledChange?: (enabled: boolean) => void;
  /** Parent renders and owns its actual Harness/plugin fields and validation. */
  children?: ReactNode;
  fields?: ReactNode;
  dirty: boolean;
  pending?: boolean;
  disabled?: boolean;
  validationError?: ReactNode;
  saveError?: ReactNode;
  onSave?: () => void;
  onDiscard?: () => void;
  className?: string;
}

export type IntegrationSettingsProps = IntegrationFormProps | IntegrationReferenceProps;

/** No schema, persistence, credential creation, or optimistic business state is built in. */
export function IntegrationSettings(props: IntegrationSettingsProps) {
  if (props.variant === 'reference') return <ReferenceIntegrationSettings {...props}/>;
  return <IntegrationForm {...props}/>;
}

function IntegrationForm({name, logo, count, meta, enabled, onEnabledChange, children, fields, dirty, pending = false, disabled = false, validationError, saveError, onSave, onDiscard, className = ''}: IntegrationFormProps) {
  const id = useId();
  const locked = pending || disabled;
  const canSave = dirty && !locked && !validationError && !!onSave;
  return <section className={`integration-settings ${className}`} data-variant="integration" aria-label={`${name} settings`} aria-busy={pending} data-capture-root>
    <header className="integration-settings__head">
      {logo && <span className="integration-settings__logo">{logo}</span>}
      <span className="integration-settings__who"><span className="integration-settings__name"><span title={name}>{name}</span>{count !== undefined && <span className="integration-settings__count">{count}</span>}</span>{meta && <span className="integration-settings__meta" title={meta}>{meta}</span>}</span>
      {enabled !== undefined && <button className="integration-settings__switch" type="button" role="switch" aria-label={`${name} enabled`} aria-checked={enabled} disabled={locked || !onEnabledChange} onClick={() => onEnabledChange?.(!enabled)}><span/></button>}
    </header>
    <form aria-label={`${name} configuration`} aria-describedby={validationError || saveError ? `${id}-error` : undefined} onSubmit={event => {event.preventDefault(); if (canSave) onSave?.();}}>
      <fieldset className="integration-settings__fields" disabled={locked}>{fields ?? children}</fieldset>
      {(validationError || saveError) && <p id={`${id}-error`} className="integration-settings__form-error" role="alert">{validationError || saveError}</p>}
      <div className="integration-settings__save" data-open={dirty || pending || !!saveError} inert={!dirty && !pending && !saveError}>
        <div className="integration-settings__save-inner"><span className="integration-settings__save-text" role="status">{pending ? 'Saving…' : 'Unsaved changes'}</span><div className="integration-settings__save-actions">
          <button className="integration-settings__btn" type="button" disabled={locked || !dirty || !onDiscard} onClick={onDiscard}>Discard</button>
          <button className="integration-settings__btn integration-settings__btn--primary" type="submit" disabled={!canSave}>{pending ? 'Saving…' : 'Save'}</button>
        </div></div>
      </div>
    </form>
  </section>;
}

// Geometry transcribed from the public preview's rendered SVGs; see study notes.
const paths = {
  check: 'm3.5 8.5 3 3 6-7',
  clock: 'M8 14.5a6.5 6.5 0 1 0 0-13 6.5 6.5 0 0 0 0 13ZM8 4.5V8l2.5 1.5',
  search: 'M7 12a5 5 0 1 0 0-10 5 5 0 0 0 0 10ZM13.5 13.5 10.6 10.6',
  copy: 'M5.5 5.5V3.5a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v6a1 1 0 0 1-1 1h-2M3.5 5.5h6a1 1 0 0 1 1 1v6a1 1 0 0 1-1 1h-6a1 1 0 0 1-1-1v-6a1 1 0 0 1 1-1Z',
  eye: 'M2 8s2.2-4.5 6-4.5S14 8 14 8s-2.2 4.5-6 4.5S2 8 2 8ZM8 9.8a1.8 1.8 0 1 0 0-3.6 1.8 1.8 0 0 0 0 3.6Z',
  hidden: 'M2 8s2.2-4.5 6-4.5S14 8 14 8s-2.2 4.5-6 4.5S2 8 2 8ZM2.5 2.5l11 11',
  key: 'M10.5 1.5a4 4 0 0 0-3.86 5.05L1.8 11.4a1 1 0 0 0-.3.7v1.9a.5.5 0 0 0 .5.5h1.9a.5.5 0 0 0 .5-.5V13h1v-1h1v-1l.95-.95A4 4 0 1 0 10.5 1.5Zm1 4a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z',
};
function Icon({name, pop = false}: {name: keyof typeof paths; pop?: boolean}) {
  return <svg className={`integration-settings__icon${pop ? ' integration-settings__icon--pop' : ''}`} width="16" height="16" viewBox="0 0 16 16" fill={name === 'key' ? 'currentColor' : 'none'} stroke={name === 'key' ? undefined : 'currentColor'} strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={paths[name]} /></svg>;
}

function domainError(value: string) {
  if (!value || /^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/i.test(value.trim())) return undefined;
  return "That doesn't look like a domain – try something like yourstore.com";
}

function ReferenceIntegrationSettings({name, logo, count, meta, value, dirty, onChange, onSave, onDiscard, timeZones, siteHint, validateSite = domainError, onGenerateKey, keyPending = false, keyIsNew = false, onCopyKey, className = ''}: IntegrationReferenceProps) {
  const id = useId();
  const [menuOpen, setMenuOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [revealed, setRevealed] = useState(keyIsNew);
  const [copied, setCopied] = useState(false);
  const zoneRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const copyTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const siteError = validateSite(value.siteUrl);
  const choices = timeZones.filter(zone => zone.toLocaleLowerCase().includes(query.toLocaleLowerCase()));
  const change = (patch: Partial<IntegrationValues>) => onChange({...value, ...patch});

  useEffect(() => {if (!keyPending) {setRevealed(keyIsNew); setCopied(false);}}, [value.apiKey, keyIsNew, keyPending]);
  useEffect(() => () => clearTimeout(copyTimer.current), []);
  useEffect(() => {
    if (!menuOpen) return;
    const outside = (event: PointerEvent) => {if (!zoneRef.current?.contains(event.target as Node)) setMenuOpen(false);};
    document.addEventListener('pointerdown', outside);
    return () => document.removeEventListener('pointerdown', outside);
  }, [menuOpen]);

  const closeMenu = () => {setMenuOpen(false); triggerRef.current?.focus();};
  async function copyKey() {
    try {
      if (onCopyKey) await onCopyKey(value.apiKey);
      else await navigator.clipboard.writeText(value.apiKey);
      setCopied(true);
      clearTimeout(copyTimer.current);
      copyTimer.current = setTimeout(() => setCopied(false), 1400);
    } catch {setCopied(false);}
  }

  return <section className={`integration-settings ${className}`} aria-label={`${name} settings`} data-capture-root>
    <header className="integration-settings__head">
      <span className="integration-settings__logo">{logo}</span>
      <span className="integration-settings__who">
        <span className="integration-settings__name"><span title={name}>{name}</span>{count !== undefined && <span className="integration-settings__count">{count}</span>}</span>
        <span className="integration-settings__meta" title={value.enabled ? meta : 'Paused – no data is synced'}>{value.enabled ? meta : 'Paused – no data is synced'}</span>
      </span>
      <button className="integration-settings__switch" type="button" role="switch" aria-label={`${name} sync`} aria-checked={value.enabled} onClick={() => {setMenuOpen(false); change({enabled: !value.enabled});}}><span /></button>
    </header>
    <div className="integration-settings__fold" data-open={value.enabled} inert={!value.enabled}>
      <div className="integration-settings__fold-inner">
        <div className="integration-settings__section">
          <span className="integration-settings__label">API key</span>
          {!value.apiKey ? <button type="button" className="integration-settings__generate" disabled={keyPending || !onGenerateKey} onClick={onGenerateKey}>
            <span className={keyPending ? 'integration-settings__shimmer' : undefined} data-text={keyPending ? 'Generating…' : undefined}>{keyPending ? 'Generating…' : 'Generate a new API key'}</span><Icon name="key" />
          </button> : <div className="integration-settings__key" data-fresh={keyIsNew && revealed}>
            <code>{revealed ? value.apiKey : `${value.apiKey.slice(0, 8)}••••••••••••••${value.apiKey.slice(-4)}`}</code>
            <button type="button" className="integration-settings__mini" aria-label={revealed ? 'Hide key' : 'Show key'} onClick={() => setRevealed(!revealed)}><Icon name={revealed ? 'hidden' : 'eye'} /></button>
            <button type="button" className="integration-settings__mini" aria-label={copied ? 'Copied' : 'Copy key'} onClick={copyKey} data-copied={copied}><Icon name={copied ? 'check' : 'copy'} pop={copied} /></button>
            <button type="button" className="integration-settings__regen" aria-label="Regenerate" disabled={keyPending || !onGenerateKey} onClick={onGenerateKey}>{keyPending ? <span className="integration-settings__spinner" aria-label="Generating" /> : 'Regenerate'}</button>
          </div>}
          {value.apiKey && keyIsNew && revealed && <p key={copied ? 'copied' : 'fresh'} className="integration-settings__note" role="status">{copied ? 'Copied to clipboard.' : 'Copy it now – it is shown in full only once.'}</p>}
        </div>
        <div className="integration-settings__section">
          <label className="integration-settings__label" htmlFor={id}>Site address</label>
          <div className="integration-settings__field" data-invalid={Boolean(siteError)}>
            <span className="integration-settings__prefix">https://</span>
            <input id={id} value={value.siteUrl} onChange={event => change({siteUrl: event.target.value.replace(/^https?:\/\//i, '')})} placeholder="yourstore.com" inputMode="url" autoComplete="off" spellCheck={false} aria-invalid={Boolean(siteError)} aria-describedby={`${id}-hint`} />
            {!siteError && value.siteUrl && <span className="integration-settings__ok"><Icon name="check" /></span>}
          </div>
          {(siteError || siteHint) && <p className="integration-settings__hint" id={`${id}-hint`} data-error={Boolean(siteError)}>{siteError || siteHint}</p>}
        </div>
        <div className="integration-settings__section">
          <span className="integration-settings__label" id={`${id}-tz`}>Time zone</span>
          <div className="integration-settings__zone" ref={zoneRef} onKeyDown={event => {
            if (event.key === 'Escape' && menuOpen) {event.preventDefault(); closeMenu();}
            if ((event.key === 'ArrowDown' || event.key === 'ArrowUp') && menuOpen) {
              event.preventDefault();
              const options = [...(zoneRef.current?.querySelectorAll<HTMLButtonElement>('[role="option"]') ?? [])];
              const index = options.indexOf(document.activeElement as HTMLButtonElement);
              options[(index + (event.key === 'ArrowDown' ? 1 : -1) + options.length) % options.length]?.focus();
            }
          }}>
            <button ref={triggerRef} type="button" className="integration-settings__field integration-settings__zone-btn" aria-haspopup="listbox" aria-expanded={menuOpen} aria-labelledby={`${id}-tz`} aria-controls={`${id}-zones`} onClick={() => {setQuery(''); setMenuOpen(!menuOpen);}}>
              <span title={value.timeZone}>{value.timeZone}</span><Icon name="clock" />
            </button>
            {menuOpen && <div className="integration-settings__menu">
              <div className="integration-settings__menu-search"><Icon name="search" /><input autoFocus aria-label="Search time zones" placeholder="Search city or offset" value={query} onChange={event => setQuery(event.target.value)} /></div>
              <div className="integration-settings__menu-list" role="listbox" id={`${id}-zones`} aria-labelledby={`${id}-tz`}>
                {choices.map(zone => <button key={zone} type="button" role="option" aria-selected={zone === value.timeZone} className="integration-settings__option" onClick={() => {change({timeZone: zone}); closeMenu();}}>{zone}{zone === value.timeZone && <Icon name="check" pop />}</button>)}
                {!choices.length && <span className="integration-settings__empty">No time zone matches.</span>}
              </div>
            </div>}
          </div>
        </div>
        <div className="integration-settings__save" data-open={dirty} inert={!dirty}>
          <div className="integration-settings__save-inner">
            <span className="integration-settings__save-text">Unsaved changes</span>
            <div className="integration-settings__save-actions">
              <button className="integration-settings__btn" type="button" onClick={() => {setMenuOpen(false); onDiscard();}}>Discard</button>
              <button className="integration-settings__btn integration-settings__btn--primary" type="button" disabled={Boolean(siteError)} onClick={() => onSave(value)}>Save</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  </section>;
}

.integration-settings{--isc-ease:cubic-bezier(.22,1,.36,1);--isc-shadow:0 0 0 .5px #0000000f,0 1px 1px -1px #0000001a,0 1px 2px #0000000d;box-sizing:border-box;width:500px;max-width:100%;background:#fff;border-radius:10px;box-shadow:var(--isc-shadow);color:rgba(0,0,0,.88);font:400 13px/20px Inter,'Inter Variable',InterVariable,ui-sans-serif,system-ui,sans-serif;text-align:left;letter-spacing:normal}
.integration-settings *{box-sizing:border-box}
.integration-settings button,.integration-settings input{font:inherit;letter-spacing:inherit;color:inherit;border:0;margin:0;outline:none}
.integration-settings button{cursor:pointer;background:none;padding:0;text-align:left}
.integration-settings button:disabled{cursor:default}
.integration-settings button:focus-visible{outline:2px solid #3687f4;outline-offset:3px}
.integration-settings__head{display:flex;align-items:center;gap:12px;padding:16px}
.integration-settings__logo{display:grid;place-items:center;width:40px;height:40px;flex:none;border-radius:8px;background:white;box-shadow:var(--isc-shadow);overflow:hidden}
.integration-settings__logo img,.integration-settings__logo svg{display:block;width:22px;height:22px}
.integration-settings__who{display:grid;flex:1;min-width:0}
.integration-settings__name{display:flex;align-items:center;gap:8px;font-size:15px;line-height:24px;font-weight:500;color:#000;min-width:0}
.integration-settings__name>span:first-child,.integration-settings__meta{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.integration-settings__count{flex:none;border-radius:5px;background:#0000000f;padding:0 5px;font-size:11px;line-height:16px;font-weight:500;font-variant-numeric:tabular-nums;color:#0000009c}
.integration-settings__meta{font-size:12px;line-height:16px;color:#00000073}
.integration-settings .integration-settings__switch{position:relative;flex:none;width:28px;height:16px;border-radius:8px;background:#00000021;transition:background-color .22s}
.integration-settings__switch[aria-checked=true]{background:rgba(0,96,226,.765)}
.integration-settings__switch>span{position:absolute;left:2px;top:2px;width:12px;height:12px;background:#fff;border-radius:50%;box-shadow:var(--isc-shadow);transition:transform .28s var(--isc-ease)}
.integration-settings__switch[aria-checked=true]>span{transform:translateX(12px)}
.integration-settings__fold{display:grid;grid-template-rows:0fr;opacity:0;transition:grid-template-rows .42s var(--isc-ease),opacity .26s}
.integration-settings__fold[data-open=true]{grid-template-rows:1fr;opacity:1}
.integration-settings__fold-inner{min-height:0;overflow:hidden}
.integration-settings__fold[data-open=true]>.integration-settings__fold-inner{overflow:visible}
.integration-settings__section{padding:14px 16px 16px;border-top:1px solid #0000000f}
.integration-settings__label{display:block;font-weight:500;margin:0 0 6px}
.integration-settings .integration-settings__generate{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;height:32px;padding:0 8px 0 10px;border-radius:8px;background:#00000008;box-shadow:inset 0 0 0 .5px #0000000f;color:#0000009c;transition:background-color .16s,color .16s}
.integration-settings__generate>.integration-settings__icon{color:#00000073}
.integration-settings .integration-settings__generate:hover:not(:disabled){background:#0000000f;color:#000000e0}
.integration-settings__icon{display:block;flex:none;width:16px;height:16px}
.integration-settings .integration-settings__field{display:flex;align-items:center;gap:2px;height:32px;width:100%;padding:0 8px 0 10px;background:#fff;border-radius:8px;box-shadow:var(--isc-shadow);transition:box-shadow .16s,background-color .16s}
.integration-settings__field:has(input:focus-visible){outline:2px solid rgba(0,96,226,.35);outline-offset:1px}
.integration-settings__field:has(input:focus):not(:has(input:focus-visible)){box-shadow:0 0 0 .5px #0000001f,0 1px 1px -1px #0000001a,0 1px 2px #0000000d}
.integration-settings__field[data-invalid=true]{background:rgba(229,72,77,.08);box-shadow:none}
.integration-settings__field[data-invalid=true]:has(input:focus-visible){outline-color:rgba(229,72,77,.35)}
.integration-settings__prefix{color:#00000045;flex:none}
.integration-settings__field input{flex:1;width:0;min-width:0;height:32px;padding:0;background:transparent}
.integration-settings__ok{display:grid;place-items:center;color:#1a9a52;animation:isc-in .24s var(--isc-ease)}
.integration-settings__hint,.integration-settings__note{margin:6px 0 0;font-size:12px;line-height:16px;color:#00000073}
.integration-settings__hint[data-error=true]{color:#e5484d}
.integration-settings__zone{position:relative}
.integration-settings .integration-settings__zone-btn{gap:8px;justify-content:space-between}
.integration-settings__zone-btn>span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.integration-settings__zone-btn>.integration-settings__icon{color:#00000073}
.integration-settings__menu{position:absolute;top:calc(100% + 6px);left:0;right:0;z-index:10;padding:4px;border-radius:10px;background:#fff;box-shadow:0 0 0 .5px #00000014,0 12px 28px -10px #00000029,0 1px 2px #0000000d;transform-origin:top;animation:isc-drop .2s var(--isc-ease)}
.integration-settings__menu-search{display:flex;align-items:center;gap:8px;height:32px;padding:0 8px;margin-bottom:4px;border-bottom:1px solid #0000000f;color:#00000073}
.integration-settings__menu-search input{width:0;min-width:0;flex:1;background:transparent;padding:0}
.integration-settings__menu-search input::placeholder{color:#00000073}
.integration-settings__menu-list{display:grid;gap:1px;max-height:200px;overflow:auto}
.integration-settings .integration-settings__option{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:32px;padding:0 8px;border-radius:6px;transition:background-color .09s ease-out;white-space:nowrap}
.integration-settings .integration-settings__option:hover,.integration-settings .integration-settings__option:focus{background:#00000008;outline:none}
.integration-settings__icon--pop{animation:isc-pop .26s var(--isc-ease)}
.integration-settings__empty{padding:8px;color:#00000073}
.integration-settings__save{display:grid;grid-template-rows:0fr;transition:grid-template-rows .36s var(--isc-ease)}
.integration-settings__save[data-open=true]{grid-template-rows:1fr}
.integration-settings__save-inner{min-height:0;overflow:hidden;display:flex;justify-content:space-between;align-items:center;gap:12px;padding:0 12px 0 16px;border-top:1px solid #0000000f;color:#0000009c}
.integration-settings__save[data-open=true]>.integration-settings__save-inner{padding-top:10px;padding-bottom:10px}
.integration-settings__save-text{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.integration-settings__save-actions{display:flex;gap:6px;flex:none}
.integration-settings .integration-settings__btn,.integration-settings .integration-settings__regen{height:28px;padding:0 10px;border-radius:6px;background:#fff;box-shadow:var(--isc-shadow);color:#000;font-weight:500;transition:box-shadow .14s,background-color .14s}
.integration-settings .integration-settings__btn:hover{background:#fafafa}
.integration-settings .integration-settings__btn--primary{min-width:56px;text-align:center;color:#fcfcfc;background:#000000e0;box-shadow:none}
.integration-settings .integration-settings__btn--primary:hover{background:#000}
.integration-settings .integration-settings__btn:disabled{opacity:.4}
.integration-settings__key{display:flex;align-items:center;gap:2px;height:36px;padding:0 4px 0 10px;border-radius:8px;background:#00000008;transition:background-color .24s;animation:isc-in .32s var(--isc-ease)}
.integration-settings__key[data-fresh=true]{background:rgba(26,154,82,.08)}
.integration-settings__key code{font:12px/16px ui-monospace,SFMono-Regular,Menlo,monospace;flex:1;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;background:none;padding:0;border:0}
.integration-settings .integration-settings__mini{display:grid;place-items:center;width:28px;height:28px;flex:none;color:#00000073;border-radius:6px;transition:background-color .14s,color .14s}
.integration-settings .integration-settings__mini:hover{background:#0000000a;color:#000000e0}
.integration-settings .integration-settings__mini[data-copied=true]{color:#1a9a52}
.integration-settings .integration-settings__regen{display:grid;place-items:center;flex:none;margin-left:2px;min-width:88px}
.integration-settings__note{color:#1a9a52;animation:isc-in .24s var(--isc-ease)}
.integration-settings__spinner{width:14px;height:14px;border:1px solid #00000020;border-top-color:currentColor;border-radius:50%;animation:isc-spin .7s linear infinite}
.integration-settings__shimmer{position:relative}
.integration-settings__shimmer::after{content:attr(data-text) / '';position:absolute;inset:0;background:linear-gradient(90deg,transparent 38%,rgba(255,255,255,.82) 50%,transparent 62%);background-size:300% 100%;background-clip:text;-webkit-background-clip:text;color:transparent;animation:isc-sweep 1.4s linear infinite}
@keyframes isc-in{from{opacity:0;transform:translateY(2px)}to{opacity:1;transform:none}}
@keyframes isc-pop{from{opacity:0;transform:scale(.5)}to{opacity:1;transform:none}}
@keyframes isc-drop{from{opacity:0;transform:translateY(-4px) scale(.98)}to{opacity:1;transform:none}}
@keyframes isc-spin{to{transform:rotate(360deg)}}
@keyframes isc-sweep{from{background-position:100% 0}to{background-position:0 0}}
@media(max-width:520px){.integration-settings__head{padding:14px 14px 14px 12px;gap:10px}.integration-settings__logo{width:36px;height:36px}.integration-settings__logo img,.integration-settings__logo svg{width:20px;height:20px}.integration-settings__section{padding:12px 12px 14px}.integration-settings__save-inner{padding-left:12px;padding-right:10px}}
@media(prefers-reduced-motion:reduce){.integration-settings *,.integration-settings *::after{animation:none!important;transition:none!important}}

.integration-settings__fields{border:0;border-top:1px solid #0000000f;padding:16px;margin:0;min-width:0;display:grid;gap:14px}
.integration-settings__form-error{padding:0 16px 12px;margin:0;font-size:12px;line-height:18px;color:#b42330}
.integration-settings[data-variant=integration] .integration-settings__switch:disabled{opacity:.45;cursor:default}
